package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.sheet.TodayChanged;
import org.springframework.context.event.EventListener;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The periods of a sheet. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final ClaimService claimService;
    private final SettingsService settings;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetService sheets, ClaimRepository claims,
            PersonRepository people, ClaimService claimService, SettingsService settings, Audit audit) {
        this.settings = settings;
        this.periods = periods;
        this.sheets = sheets;
        this.claims = claims;
        this.people = people;
        this.claimService = claimService;
        this.audit = audit;
    }

    /** The sheet's periods, by from-date. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromAsc(sheetId);
    }

    /**
     * Adds a period; refused when its to-date is before its from-date, its name is in use on the sheet or its dates
     * overlap another period's. A cap, when given, is the most OPEN or PENDING claims a person may have in it.
     */
    @Transactional
    public Period add(String by, String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        // the sheet stays locked until the transaction ends, so two periods added at once are checked in turn
        sheets.lock(sheetId);
        String trimmed = name.strip();
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts.");
        }
        if (periods.existsBySheetIdAndName(sheetId, trimmed)) {
            throw nameInUse();
        }
        if (periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, to, from)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
        }
        Period added;
        try {
            added = periods.saveAndFlush(new Period(sheetId, trimmed, from, to, cap));
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
                + " from=" + added.getFrom() + " to=" + added.getTo()
                + (added.getCap() != null ? " cap=" + added.getCap() : ""));
        return added;
    }

    /**
     * Adds one period per calendar month from the from-date's month to the to-date's month, each from the first to the
     * last day of its month and named yyyy-mm, by month. A month whose name is in use on the sheet or whose days
     * overlap a period is left out; the others are still made. Refused when the to-date is before the from-date.
     */
    @Transactional
    public List<Period> generate(String by, String sheetId, LocalDate from, LocalDate to) {
        // the sheet stays locked until the transaction ends, so periods added at once are checked in turn
        sheets.lock(sheetId);
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
        }
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (periods.existsBySheetIdAndName(sheetId, name)
                    || periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, last, first)) {
                continue;
            }
            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
                    + " from=" + added.getFrom() + " to=" + added.getTo());
            made.add(added);
        }
        return made;
    }

    /**
     * Adds the twelve monthly periods of the fiscal year FY<year>, the one starting on the first of the sheet's fiscal
     * start month in that year, exactly as {@link #generate} does for its first through its last day.
     */
    @Transactional
    public List<Period> generateFiscalYear(String by, String sheetId, int year) {
        LocalDate first = YearMonth.of(year, sheets.lock(sheetId).getFiscalStartMonth()).atDay(1);
        return generate(by, sheetId, first, first.plusYears(1).minusDays(1));
    }

    /**
     * Closes the period, fixing each person's due-total for it now (the figures of their claims due by a date in it that
     * counted at the end of its last day, skipping n/a) and its own, the sum of those.
     * Refused unless the user's role may close, and when it is already closed.
     */
    @Transactional
    public Period close(String by, String sheetId, Long id) {
        // the sheet stays locked until the transaction ends, so no claim in the period changes while it closes
        LocalDate today = sheets.lock(sheetId).getToday();
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessMay(sheetId, by, "close");
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
        }
        return close(by, sheetId, period, today, "");
    }

    /**
     * Soft-closes the period, fixing its figures as a close does while claims due by a date in it can still change. Refused
     * unless the user's role may close, and when it is already closed or soft-closed.
     */
    @Transactional
    public Period softClose(String by, String sheetId, Long id) {
        LocalDate today = sheets.lock(sheetId).getToday();
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessMay(sheetId, by, "close");
        if (period.isClosed() || period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
        }
        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period, today);
        BigDecimal total = sum(personTotals);
        period.softClose(total, personTotals, personCarried(sheetId, period, today));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + by + " period=" + saved.getName()
                + " total=" + total.toPlainString());
        return saved;
    }

    /**
     * Once the sheet's today is changed while it has grace days, closes every open period (not soft-closed) whose to-date plus them is
     * before the new today, by to-date, each as a close by hand would.
     */
    @EventListener
    @Transactional
    public void autoClose(TodayChanged change) {
        Sheet sheet = change.sheet();
        Integer graceDays = sheet.getGraceDays();
        if (graceDays == null) {
            return;
        }
        LocalDate today = sheet.getToday();
        for (Period period : periods.findBySheetIdAndClosedFalseAndToBeforeOrderByToAsc(sheet.getId(),
                today.minusDays(graceDays))) {
            // a soft-closed period keeps the figures it fixed
            if (period.isSoftClosed()) {
                continue;
            }
            close(change.by(), sheet.getId(), period, today, " auto=yes");
        }
    }

    private Period close(String by, String sheetId, Period period, LocalDate today, String auditSuffix) {
        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period, today);
        BigDecimal total = sum(personTotals);
        period.close(total, personTotals, personCarried(sheetId, period, today));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + by + " period=" + saved.getName()
                + " total=" + total.toPlainString() + auditSuffix);
        return saved;
    }

    private static BigDecimal sum(Map<Long, BigDecimal> personTotals) {
        return personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * Each person's due-total for the period now: the figures of their claims due by a date in it that counted at the end of
     * its last day, skipping n/a; 0.00 for a person with none.
     */
    private Map<Long, BigDecimal> personTotals(String sheetId, Period period, LocalDate today) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        // every person on the sheet now gets a figure, 0.00 when none of their counted claims is due by a date in it
        Map<Long, BigDecimal> personTotals = new HashMap<>();
        for (Long personId : byId.keySet()) {
            personTotals.put(personId, BigDecimal.ZERO.setScale(2));
        }
        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(c.getPersonId());
            if (person == null || !person.countsAtEndOf(c, period.getTo(), today) || !period.contains(c.getDueBy())) {
                continue;
            }
            BigDecimal figure = claimService.due(sheetId, person, c);
            if (figure != null) {
                personTotals.merge(person.getId(), figure, BigDecimal::add);
            }
        }
        return personTotals;
    }

    /**
     * Each person's carried figure for the period now: the figures of their claims belonging to a period of the sheet
     * that ends before this one starts and still open or pending at the end of its last day, skipping n/a; 0.00 for a
     * person with none.
     */
    private Map<Long, BigDecimal> personCarried(String sheetId, Period period, LocalDate today) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        List<Period> earlier = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(p -> p.getTo().isBefore(period.getFrom())).toList();
        Map<Long, BigDecimal> carried = new HashMap<>();
        for (Long personId : byId.keySet()) {
            carried.put(personId, BigDecimal.ZERO.setScale(2));
        }
        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(c.getPersonId());
            if (person == null || c.getDueBy() == null || earlier.stream().noneMatch(p -> p.contains(c.getDueBy()))
                    || !person.countsAtEndOf(c, period.getTo(), today)
                    || !c.statusAtEndOf(period.getTo()).isOpen()) {
                continue;
            }
            BigDecimal figure = claimService.due(sheetId, person, c);
            if (figure != null) {
                carried.merge(person.getId(), figure, BigDecimal::add);
            }
        }
        return carried;
    }

    /**
     * Reopens a closed or soft-closed period, making its due-total live again. Refused unless the user's role may reopen (a steward by
     * the standing rule), or when the period is not closed.
     */
    @Transactional
    public Period reopen(String by, String sheetId, Long id) {
        sheets.lock(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessMay(sheetId, by, "reopen");
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + by + " period=" + saved.getName());
        return saved;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
    }
}
package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/**
 * A period of a sheet: a name unique on the sheet and a from and to date, inclusive. A closed period keeps the
 * due-total it had when it was closed, and each person's due-total and carried figure for it then. A soft-closed period keeps them
 * the same way, but claims due by a date in it can still change.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "to_date", nullable = false)
    private LocalDate to;

    @Column(name = "claim_cap")
    private Integer cap;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false)
    private Map<Long, BigDecimal> closedPersonCarried = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, null);
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this.sheetId = sheetId;
        this.name = name;
        this.from = from;
        this.to = to;
        this.cap = cap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    /** The most OPEN or PENDING claims a person may have in the period; null for no cap. */
    public Integer getCap() {
        return cap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return Map.copyOf(closedPersonTotals);
    }

    /** Each person's carried figure fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> getClosedPersonCarried() {
        return Map.copyOf(closedPersonCarried);
    }

    /**
     * Folds the due-total and carried figure fixed for one person into another's (a person with none fixed takes them as theirs): the
     * merged person leaves the period, their figure kept under the person they were merged into.
     */
    public void mergePersonTotal(Long from, Long into) {
        BigDecimal moved = closedPersonTotals.remove(from);
        if (moved != null) {
            closedPersonTotals.merge(into, moved, BigDecimal::add);
        }
        BigDecimal carried = closedPersonCarried.remove(from);
        if (carried != null) {
            closedPersonCarried.merge(into, carried, BigDecimal::add);
        }
    }

    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** Closes the period, fixing its due-total and each person's, and each person's carried figure. */
    public void close(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        fix(total, personTotals, personCarried);
        this.closed = true;
        this.softClosed = false;
    }

    /**
     * Soft-closes the period, fixing its due-total and each person's, and each person's carried figure; claims due by a
     * date in it can still change.
     */
    public void softClose(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        fix(total, personTotals, personCarried);
        this.softClosed = true;
    }

    private void fix(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.closedTotal = total;
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
        this.closedPersonCarried.clear();
        this.closedPersonCarried.putAll(personCarried);
    }

    /** Reopens the period, closed or soft-closed: its due-total and carried figures are live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
        this.closedPersonCarried.clear();
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, Injectable, computed, inject, input, signal } from '@angular/core';
import { FigPipe } from '../../core/locale';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { ClaimLogLine, ClaimStatus, statusAtEndOf } from '../claims/claims';
import { sumSkippingNa } from '../rates/rates';
import { SettingsStore } from '../settings/settings';

export interface PeriodView {
  id: number;
  name: string;
  // Both inclusive (yyyy-mm-dd).
  from: string;
  to: string;
  // The most OPEN or PENDING claims a person may have in it (those due by a date in it); null for no cap.
  cap: number | null;
  // A closed period keeps the due-total fixed when it was closed; no claim due by a date in it can change.
  closed: boolean;
  // A soft-closed period keeps its due-total fixed the same way, but claims due by a date in it can still change.
  softClosed: boolean;
  closedTotal: string | null;
  // Each person's due-total fixed when it was closed or soft-closed, by person id; empty while it is open.
  closedPersonTotals: Record<string, string>;
  // Each person's carried figure fixed when it was closed or soft-closed, by person id; empty while it is open.
  closedPersonCarried: Record<string, string>;
}

/**
 * A claim the live rules do not leave out (deferred or held): its person, its due-by (which decides its period), the
 * figure it totals now (null for n/a), and its status and log, which decide whether it counted at the end of a period.
 */
export interface DatedFigure {
  personId: number;
  dueBy: string;
  figure: string | null;
  status: ClaimStatus;
  log: ClaimLogLine[];
}

/** Whether a claim with the status counts: open, pending or settled. */
function countingStatus(status: ClaimStatus | null | undefined): boolean {
  return status === 'OPEN' || status === 'PENDING' || status === 'SETTLED';
}

/** Whether the claim counted at the end of the day: its status then is open, pending or settled. */
function countedAtEndOf(f: DatedFigure, day: string): boolean {
  return countingStatus(statusAtEndOf(f, day));
}

/** Whether the claim counts by its status now (open, pending or settled), whatever it was at the end of the day. */
function countedNow(f: DatedFigure): boolean {
  return countingStatus(f.status);
}

/** How a period's due-total decides whether a claim counts: given the claim and the period's last day. */
export type PeriodCounting = (f: DatedFigure, lastDay: string) => boolean;

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * The fiscal year the date falls in, named FY<yyyy> by the calendar year its first day falls in: fiscal years start on
 * the first of the start month (1 to 12).
 */
export function fiscalYearOf(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

/** The period whose dates contain the date; undefined when none does. */
export function periodOn(periods: readonly PeriodView[], date: string): PeriodView | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** Whether a closed period contains the date. */
export function inClosedPeriod(periods: readonly PeriodView[], date: string): boolean {
  return periodOn(periods, date)?.closed ?? false;
}

/**
 * The person's due-total for each period, by period id: a closed one's figure fixed for them when it was closed
 * (0.00 for a person added since), else the figures now of their claims due by a date in it that counted at the end of its
 * last day, skipping n/a.
 */
export function personPeriodDueTotals(
  periods: readonly PeriodView[],
  personId: number,
  figures: readonly DatedFigure[],
  counted: PeriodCounting = countedAtEndOf,
): Map<number, string> {
  const by = new Map<number, (string | null)[]>();
  for (const p of periods) by.set(p.id, []);
  for (const f of figures) {
    if (f.personId !== personId) continue;
    const p = periodOn(periods, f.dueBy);
    if (p && counted(f, p.to)) by.get(p.id)?.push(f.figure);
  }
  return new Map(
    periods.map((p) => [
      p.id,
      p.closed || p.softClosed ? (p.closedPersonTotals[personId] ?? '0.00') : sumSkippingNa(by.get(p.id) ?? []),
    ]),
  );
}

/**
 * The person's carried figure for each period, by period id: a closed or soft-closed one's figure fixed for them when it
 * was closed (0.00 for a person added since), else the figures now of their claims belonging to a period that ends
 * before this one starts and still open or pending at the end of this one's last day, skipping n/a.
 */
export function personPeriodCarried(
  periods: readonly PeriodView[],
  personId: number,
  figures: readonly DatedFigure[],
): Map<number, string> {
  const by = new Map<number, (string | null)[]>();
  for (const p of periods) by.set(p.id, []);
  for (const f of figures) {
    if (f.personId !== personId) continue;
    const own = periodOn(periods, f.dueBy);
    if (!own) continue;
    for (const p of periods) {
      if (own.to >= p.from) continue;
      const status = statusAtEndOf(f, p.to);
      if (status === 'OPEN' || status === 'PENDING') by.get(p.id)?.push(f.figure);
    }
  }
  return new Map(
    periods.map((p) => [
      p.id,
      p.closed || p.softClosed ? (p.closedPersonCarried[personId] ?? '0.00') : sumSkippingNa(by.get(p.id) ?? []),
    ]),
  );
}

/** Each period's due-total, by period id: the sum of the people's due-totals for it. */
export function periodDueTotals(
  periods: readonly PeriodView[],
  figures: readonly DatedFigure[],
  counted: PeriodCounting = countedAtEndOf,
): Map<number, string> {
  // everyone with a figure for some period: a counted claim, or one fixed when a period closed
  const people = new Set(figures.map((f) => f.personId));
  for (const p of periods) for (const id of Object.keys(p.closedPersonTotals)) people.add(Number(id));
  const each = [...people].map((id) => personPeriodDueTotals(periods, id, figures, counted));
  return new Map(periods.map((p) => [p.id, sumSkippingNa(each.map((m) => m.get(p.id) ?? null))]));
}

/**
 * Each period's classic due-total, by period id: as periodDueTotals, but each claim counted by its status now (open,
 * pending or settled) rather than at the end of the period; a closed period still shows the figure fixed when it closed.
 */
export function classicPeriodDueTotals(
  periods: readonly PeriodView[],
  figures: readonly DatedFigure[],
): Map<number, string> {
  return periodDueTotals(periods, figures, countedNow);
}

